WITH cursos(tema, nivel) AS (
         VALUES ('Java', 'Inicial'), ('Java', 'Inicial'), ('Java', 'Medio')
       )
       SELECT DISTINCT tema, nivel FROM cursos ORDER BY nivel;

WITH a(id, nombre) AS (VALUES (1, 'Ana'), (2, 'Luz')),
            b(alumno_id, tema) AS (VALUES (1, 'SQL'))
       SELECT a.nombre, b.tema FROM a LEFT JOIN b ON a.id = b.alumno_id ORDER BY a.id;

WITH a(id, nombre) AS (VALUES (1, 'Ana')),
            b(id, alumno_id) AS (VALUES (10, 1), (20, 2))
       SELECT a.nombre, b.id FROM a RIGHT JOIN b ON a.id = b.alumno_id ORDER BY b.id;

WITH a(id) AS (VALUES (1), (2)), b(id) AS (VALUES (2), (3))
       SELECT a.id AS origen, b.id AS destino
       FROM a FULL OUTER JOIN b ON a.id = b.id ORDER BY COALESCE(a.id, b.id);

WITH dias(dia) AS (VALUES ('Lun'), ('Mar')),
            turnos(turno) AS (VALUES ('Mañana'), ('Tarde'))
       SELECT dia, turno FROM dias CROSS JOIN turnos ORDER BY dia, turno;

WITH a(id, nombre) AS (VALUES (1, 'SQL')),
            b(id, nivel) AS (VALUES (1, 'Inicial'))
       SELECT * FROM a JOIN b USING (id);

WITH datos(valor) AS (VALUES ('{"total":25}'))
       SELECT valor -> '$.total' AS json, valor ->> '$.total' AS numero,
              typeof(valor ->> '$.total') AS tipo FROM datos;

WITH b(id,tema,minutos) AS (VALUES (1,'Java',20), (2,'Java',35), (3,'SQL',30))
       SELECT tema, minutos, row_number() OVER (PARTITION BY tema ORDER BY minutos DESC, id) AS posicion
       FROM b ORDER BY tema, posicion;

CREATE TABLE plan_pk (
           curso TEXT NOT NULL, numero INTEGER NOT NULL,
           PRIMARY KEY (curso, numero)
       );
       INSERT INTO plan_pk VALUES ('SQL', 1), ('SQL', 2), ('Java', 1);
       SELECT curso, numero FROM plan_pk ORDER BY curso, numero;

PRAGMA foreign_keys = ON;
       CREATE TABLE plan_padre (id INTEGER PRIMARY KEY);
       CREATE TABLE plan_hijo (
           id INTEGER PRIMARY KEY, plan_id INTEGER,
           FOREIGN KEY (plan_id) REFERENCES plan_padre(id) ON DELETE CASCADE
       );
       INSERT INTO plan_padre VALUES (1), (2);
       INSERT INTO plan_hijo VALUES (10, 1), (20, 2);
       DELETE FROM plan_padre WHERE id = 1;
       SELECT id, plan_id FROM plan_hijo;

CREATE TABLE plan_unico (tema TEXT, nivel TEXT, UNIQUE (tema, nivel));
       INSERT INTO plan_unico VALUES ('Java','Base'), ('Java','Medio');
       INSERT OR IGNORE INTO plan_unico VALUES ('Java','Base');
       SELECT tema, nivel FROM plan_unico ORDER BY nivel;

CREATE TABLE plan_check (minutos INTEGER CHECK (minutos BETWEEN 1 AND 180));
       INSERT INTO plan_check VALUES (25), (NULL);
       INSERT OR IGNORE INTO plan_check VALUES (0);
       SELECT minutos FROM plan_check ORDER BY minutos IS NULL;

CREATE TABLE plan_requerido (tema TEXT NOT NULL);
       INSERT INTO plan_requerido VALUES ('SQL'), ('');
       INSERT OR IGNORE INTO plan_requerido VALUES (NULL);
       SELECT COUNT(*) AS filas, SUM(tema = '') AS vacios FROM plan_requerido;

CREATE TABLE plan_default (id INTEGER PRIMARY KEY, nivel TEXT DEFAULT 'inicial');
       INSERT INTO plan_default (id) VALUES (1);
       INSERT INTO plan_default VALUES (2, NULL);
       SELECT id, nivel FROM plan_default ORDER BY id;

CREATE TABLE plan_total (
           unidades INTEGER, minutos INTEGER,
           total INTEGER GENERATED ALWAYS AS (unidades * minutos) STORED
       );
       INSERT INTO plan_total (unidades, minutos) VALUES (3, 20);
       UPDATE plan_total SET unidades = 4;
       SELECT total FROM plan_total;

CREATE TABLE plan_strict (id INTEGER PRIMARY KEY, minutos INTEGER NOT NULL) STRICT;
       INSERT INTO plan_strict VALUES (1, '25');
       SELECT id, minutos, typeof(minutos) FROM plan_strict;

CREATE TABLE plan_compuesto (
           tema TEXT, numero INTEGER,
           PRIMARY KEY (tema, numero)
       ) WITHOUT ROWID;
       INSERT INTO plan_compuesto VALUES ('SQL', 2), ('SQL', 1);
       SELECT tema, numero FROM plan_compuesto ORDER BY tema, numero;

CREATE TABLE plan_afinidad (texto TEXT, numero NUMERIC);
       INSERT INTO plan_afinidad VALUES (25, '25');
       SELECT typeof(texto), typeof(numero) FROM plan_afinidad;

CREATE TABLE resumen_vcode AS
       SELECT 'SQL' AS tema, 40 AS total;
       SELECT tema, total FROM resumen_vcode;

CREATE TABLE plan_parcial (id INTEGER PRIMARY KEY, activo INTEGER, fecha TEXT);
       CREATE INDEX pendientes_vcode ON plan_parcial (fecha) WHERE activo = 1;
       INSERT INTO plan_parcial VALUES (1,1,'2026-01-01'), (2,0,'2026-01-01');
       SELECT id FROM plan_parcial WHERE activo = 1 AND fecha = '2026-01-01';

CREATE TABLE plan_expr (tema TEXT);
       CREATE INDEX tema_normalizado ON plan_expr (lower(tema));
       INSERT INTO plan_expr VALUES ('SQL'), ('Java');
       SELECT tema FROM plan_expr WHERE lower(tema) = 'sql';

CREATE TABLE plan_trigger (id INTEGER PRIMARY KEY, minutos INTEGER);
       CREATE TABLE registro_trigger (anterior INTEGER, nuevo INTEGER);
       CREATE TRIGGER historial_vcode AFTER UPDATE OF minutos ON plan_trigger
       BEGIN
           INSERT INTO registro_trigger VALUES (OLD.minutos, NEW.minutos);
       END;
       INSERT INTO plan_trigger VALUES (1, 20);
       UPDATE plan_trigger SET minutos = 35 WHERE id = 1;
       SELECT anterior, nuevo FROM registro_trigger;

CREATE VIRTUAL TABLE docs_vcode USING fts4(tema, texto);
       INSERT INTO docs_vcode VALUES ('Java', 'clases y genericos'), ('SQL', 'tablas y consultas');
       SELECT tema FROM docs_vcode WHERE docs_vcode MATCH 'consultas';

CREATE VIRTUAL TABLE lista_vcode USING fts4(tema, notas);
       INSERT INTO lista_vcode VALUES ('HTML', 'guía de etiquetas'), ('SQL', 'guía de tablas');
       SELECT tema FROM lista_vcode WHERE lista_vcode MATCH 'tablas';

CREATE TABLE borrador_vcode (id INTEGER);
       DROP TABLE borrador_vcode;
       SELECT COUNT(*) AS tablas FROM sqlite_schema WHERE name = 'borrador_vcode';

CREATE TABLE plan_sin_indice (tema TEXT);
       CREATE INDEX indice_vcode ON plan_sin_indice (tema);
       DROP INDEX indice_vcode;
       SELECT COUNT(*) AS indices FROM sqlite_schema WHERE name = 'indice_vcode';

CREATE TABLE plan_lectura (tema TEXT);
       INSERT INTO plan_lectura VALUES ('SQL');
       CREATE VIEW lectura_vcode AS SELECT tema FROM plan_lectura;
       DROP VIEW lectura_vcode;
       SELECT tema FROM plan_lectura;

CREATE TABLE plan_sin_trigger (id INTEGER);
       CREATE TRIGGER disparador_vcode AFTER INSERT ON plan_sin_trigger BEGIN SELECT 1; END;
       DROP TRIGGER disparador_vcode;
       SELECT COUNT(*) AS disparadores FROM sqlite_schema WHERE name = 'disparador_vcode';

CREATE TABLE plan_replace (id INTEGER PRIMARY KEY, tema TEXT, minutos INTEGER DEFAULT 0);
       INSERT INTO plan_replace VALUES (1, 'SQL', 35);
       REPLACE INTO plan_replace (id, tema) VALUES (1, 'Java');
       SELECT id, tema, minutos FROM plan_replace;

