CREATE TABLE restaurar_vcode (tema TEXT);
       BEGIN;
       INSERT INTO restaurar_vcode VALUES ('SQL');
       SAVEPOINT propuesta;
       INSERT INTO restaurar_vcode VALUES ('React');
       ROLLBACK TO propuesta;
       RELEASE propuesta;
       COMMIT;
       SELECT tema FROM restaurar_vcode;

CREATE TABLE liberar_vcode (tema TEXT);
       BEGIN;
       SAVEPOINT interno;
       INSERT INTO liberar_vcode VALUES ('SQL');
       RELEASE interno;
       ROLLBACK;
       SELECT COUNT(*) AS cambios_guardados FROM liberar_vcode;

